const email = $input.first().json;

const de = (email.from || '').toLowerCase();
const para = (email.to || '').toLowerCase();
const asunto = (email.subject || '').toLowerCase();
const cuerpo = (email.text || email.html || '').toLowerCase();

// === FILTRO ANTI-BUCLE: ignorar correos de noxertez ===
const esPropio = de.includes('noxertez@gmail.com') || 
                 de.includes('@noxertez.com') ||
                 de.includes('mailer-daemon') ||
                 de.includes('postmaster');

// === FILTRO ANTI-SPAM ===
const dominiosSpam = [
  'wallapop', 'vinted', 'milanuncios', 'vibbo', 'todocoleccion',
  'noreply', 'no-reply', 'donotreply', 'do-not-reply',
  'newsletter', 'notification', 'notifications', 'marketing',
  'support@', 'hello@', 'team@', 'news@',
  'mailchimp', 'sendgrid', 'mailjet', 'brevo', 'sendinblue',
  'google.com', 'facebook.com', 'instagram.com', 'twitter.com',
  'linkedin.com', 'amazon.com', 'ebay.com'
];
const esSpam = dominiosSpam.some(d => de.includes(d));

// === FILTRO ASUNTO SPAM ===
const asuntosSpam = [
  'unsubscribe', 'darse de baja', 'newsletter', 'oferta especial',
  'promocion', 'descuento', 'publicidad', 'notificacion automatica',
  'do not reply', 'automatic reply', 'out of office', 'fuera de oficina'
];
const asuntoEsSpam = asuntosSpam.some(a => asunto.includes(a));

// === DETECTAR A QUÉ CORREO FUE ENVIADO ===
let tipoPedido = 'desconocido';
if (para.includes('pedidos@noxertez.com')) tipoPedido = 'pedido_directo';
else if (para.includes('info@noxertez.com')) tipoPedido = 'info_general';
else if (para.includes('influencer@noxertez.com')) tipoPedido = 'influencer';
else if (para.includes('ayuda@noxertez.com')) tipoPedido = 'soporte';
else if (para.includes('noxertez@gmail.com')) tipoPedido = 'gmail_directo';

// === RESULTADO ===
const ignorar = esPropio || esSpam || asuntoEsSpam;

return [{ json: {
  ignorar,
  motivo_ignorar: esPropio ? 'correo_propio' : esSpam ? 'spam_remitente' : asuntoEsSpam ? 'spam_asunto' : null,
  tipo: tipoPedido,
  de: email.from || '',
  para: email.to || '',
  asunto: email.subject || '',
  cuerpo_raw: (email.text || '').substring(0, 500),
  fecha: new Date().toISOString()
}}];

const d = $input.first().json;

// Extraer nombre del remitente
const deRaw = d.de || '';
let nombre = deRaw.includes('<') ? deRaw.split('<')[0].trim().replace(/"/g, '') : deRaw.split('@')[0];
if (!nombre) nombre = 'Cliente sin nombre';

// Extraer teléfono si aparece en el cuerpo
const telMatch = d.cuerpo_raw.match(/(?:\+34|0034)?\s*[6789]\d{8}/);
const telefono = telMatch ? telMatch[0].replace(/\s/g, '') : '';

// Número de pedido único
const numero_pedido = 'EMAIL-' + Date.now();

// Preparar items básicos (el cuerpo libre sin parsear)
const items = [{ 
  referencia: 'PENDIENTE', 
  nombre: 'Ver correo - completar manualmente', 
  cantidad: 1, 
  precio_unit: 0, 
  subtotal: 0 
}];

// Etiqueta según tipo
const etiquetas = {
  'pedido_directo': '📦 PEDIDO',
  'info_general': 'ℹ️ CONSULTA',
  'influencer': '🌟 INFLUENCER',
  'soporte': '🆘 AYUDA',
  'gmail_directo': '📧 GMAIL',
  'desconocido': '❓ REVISAR'
};
const etiqueta = etiquetas[d.tipo] || '❓ REVISAR';

return [{ json: {
  numero_pedido,
  nombre_cliente: nombre,
  email_cliente: deRaw,
  telefono,
  tipo: d.tipo,
  etiqueta,
  items_json: JSON.stringify(items),
  notas: `${etiqueta} | Asunto: ${d.asunto} | De: ${deRaw} | Mensaje: ${d.cuerpo_raw}`,
  fecha_pedido: d.fecha
}}];
